export const volcengineTtsVoices: CreatorTtsVoice[] = [
  ...smallModelVoices,
  ...bigModelVoices
].map(voice => ({ ...voice, provider: 'volcengine' }));

export function isVolcengineTtsCluster(value: string): value is VolcengineTtsCluster {
  return volcengineTtsClusters.some(cluster => cluster === value);
}

export function resolveVolcengineTtsRoute(model: string, voiceId: string): {
  api: 'v1' | 'v3';
  cluster: string;
  resourceId: string;
} {
  const inferred = inferResourceId(model.trim(), voiceId.trim());
  if (inferred.startsWith('seed-')) {
    return { api: 'v3', cluster: inferred, resourceId: inferred };
  }
  return { api: 'v1', cluster: inferred || 'volcano_tts', resourceId: inferred || 'volcano_tts' };
}

function inferResourceId(model: string, voiceId: string): string {
  if (/^S_/i.test(voiceId)) {
    return model.startsWith('volcano_icl') || model.startsWith('seed-icl')
      ? model
      : 'seed-icl-2.0';
  }
  if (
    /^ICL_/i.test(voiceId)
    || /_uranus_bigtts$|_jupiter_bigtts$|^saturn_/i.test(voiceId)
  ) {
    return model.startsWith('seed-tts-2') ? model : 'seed-tts-2.0';
  }
  if (/_mars_bigtts$|_moon_bigtts$|_wvae_bigtts$/i.test(voiceId)) {
    return model.startsWith('seed-tts-1') ? model : 'seed-tts-1.0';
  }
  if (model.startsWith('seed-') || model.startsWith('volcano_')) return model;
  return 'volcano_tts';
}

export function listVolcengineTtsVoices(model: string): CreatorTtsVoice[] {
  const normalized = model.trim() || 'volcano_tts';
  return volcengineTtsVoices
    .filter(voice => (voice.supportedModels ?? []).some(candidate => candidate === normalized))
    .map(voice => ({ ...voice }));
}

export function defaultVolcengineVoiceId(model: string): string {
  const normalized = model.trim() || 'volcano_tts';
  if (normalized.startsWith('seed-tts-2')) return 'zh_female_cancan_uranus_bigtts';
  if (normalized.startsWith('seed-tts-1')) return 'zh_female_tianmeitaozi_mars_bigtts';
  if (
    normalized.startsWith('seed-icl')
    || normalized.startsWith('volcano_icl')
    || normalized.startsWith('volcano_mega')
  ) {
    return '';
  }
  const voices = listVolcengineTtsVoices(normalized);
  return voices.find(voice => voice.recommended)?.id ?? voices[0]?.id ?? 'BV001_streaming';
}

export function volcengineSpeechRate(speed: number): number {
  return Math.min(100, Math.max(-50, Math.round((speed - 1) * 100)));
}
